function setStraightStep(step){if(selectedBackingGuide!=='straight'||backingGuideMode!=='learn'||!Number.isInteger(step)||step<0||step>=straightLearningStages().length)return;straightStep=step;straightAnswerChoice=null;renderBackingGuide();const h=document.getElementById('straightStageTitle');h.focus({preventScroll:true});h.scrollIntoView({block:'start'});}
function setStraightDrift(drift){if(selectedBackingGuide!=='straight'||backingGuideMode!=='learn'||!['right','left'].includes(drift))return;straightDrift=drift;straightAnswerChoice=null;renderBackingGuide();document.getElementById('straightStageTitle').focus({preventScroll:true});}
function answerStraightLearning(choice){if(selectedBackingGuide!=='straight'||backingGuideMode!=='learn'||!Number.isInteger(choice)||choice<0||choice>1)return;straightAnswerChoice=choice;renderBackingGuide();const f=document.getElementById('straightLearningFeedback');f.setAttribute('tabindex','-1');f.focus({preventScroll:true});f.scrollIntoView({block:'nearest'});}
function openStraightLearningTest(key){if(selectedBackingGuide!=='straight'||!['straight','straight-left','center'].includes(key))return;openScreen('practiceyard');window.showPracticeLesson(key);}
